function bibliography(entry, style){
  var e=entry||{};
  var s=String(style||'apa').toLowerCase();
  var author=String(e.author||'').trim();
  var title=String(e.title||'').trim();
  var year=String(e.year||'').trim();
  var pub=String(e.publisher||'').trim();
  var url=String(e.url||'').trim();
  if(!author && !title) return {ok:false, reason:'请至少填写作者或标题'};
  var out;
  if(s==='mla'){
    out=(author?author+'. ':'')+(title?'"'+title+'." ':'')+(pub?pub+', ':'')+(year?year+'. ':'')+url;
  } else if(s==='chicago'){
    out=(author?author+'. ':'')+(title?title+'. ':'')+(pub?pub+', ':'')+(year?year+'. ':'')+url;
  } else if(s==='gbt'){
    out=(author?author+'. ':'')+(title?title+'[M]. ':'')+(pub?pub+', ':'')+(year?year+'. ':'')+url;
  } else {
    s='apa';
    out=(author?author+' ':'')+'('+(year||'n.d.')+'). '+(title?title+'. ':'')+(pub?pub+'. ':'')+url;
  }
  return {ok:true, text:out.replace(/\s+/g,' ').trim(), style:s};
}

var EXPORTS={bibliography:bibliography};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BibForgePure = EXPORTS; }
